"""The C++ smokes' and metis::Live's fixtures, committed into metis-lang
(runtime/fixtures) so its ctest runs without Python (runtime-binding step 1, the
architect's ruling). gen_fw_artifact.py, gen_ir_artifact.py and
gen_live_goldens.py produce them (as tests/test_cpp_parity.py does); this prefixes each file with one
header line naming the metispy commit and the generator file's hash:

  # GENERATED by metispy <commit> tools/gen_fw_artifact.py sha256:<hex> — do not edit

  python tools/gen_smoke_fixtures.py [DIR]          write (default: LANG/runtime/fixtures)
  python tools/gen_smoke_fixtures.py --check [DIR]  regenerate and diff (CI)

--check compares every line but the commit: a changed generator (its
hash) or a changed body is drift, caught on the side that owns the
generator. A tree with uncommitted changes writes '<commit>+dirty'."""

import argparse
import difflib
import hashlib
import re
import subprocess
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(Path(__file__).resolve().parent))
from langpath import LANG  # noqa: E402

GENERATORS = {
    "tools/gen_fw_artifact.py": ["fw_rover_v1.txt", "fw_rover_v2.txt",
                                 "fw_rover_expect.txt"],
    "tools/gen_ir_artifact.py": ["ir_rover_artifact.txt",
                                 "ir_rover_expect.txt"],
    # metis::Live's goldens on public corpus programs (runtime-binding K1/K2)
    "tools/gen_live_goldens.py": ["live_cascade.wire", "live_cascade.txt",
                                  "live_love_triangle.wire",
                                  "live_love_triangle.txt"],
}
HEADER = re.compile(r"^# GENERATED by metispy (\S+) (\S+) sha256:([0-9a-f]+)")


def commit() -> str:
    git = ["git", "-C", str(ROOT)]
    head = subprocess.run(git + ["rev-parse", "--short=12", "HEAD"],
                          capture_output=True, text=True, check=True)
    dirty = subprocess.run(git + ["status", "--porcelain"],
                           capture_output=True, text=True, check=True)
    return head.stdout.strip() + ("+dirty" if dirty.stdout.strip() else "")


def generate(out: Path) -> dict:
    """{name: text} with the header line, every fixture."""
    rev = commit()
    files = {}
    for gen, names in GENERATORS.items():
        digest = hashlib.sha256((ROOT / gen).read_bytes()).hexdigest()
        subprocess.run([sys.executable, str(ROOT / gen), str(out)],
                       cwd=ROOT, check=True, stdout=subprocess.DEVNULL)
        for name in names:
            files[name] = (f"# GENERATED by metispy {rev} {gen} "
                           f"sha256:{digest} — do not edit\n"
                           + (out / name).read_text())
    return files


def sans_commit(text: str) -> list:
    lines = text.splitlines(keepends=True)
    if lines:
        lines[0] = HEADER.sub(r"# GENERATED by metispy * \2 sha256:\3",
                              lines[0])
    return lines


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("dir", nargs="?", type=Path,
                    default=LANG / "runtime" / "fixtures")
    ap.add_argument("--check", action="store_true",
                    help="regenerate and diff against DIR; exit 1 on drift")
    a = ap.parse_args()
    with tempfile.TemporaryDirectory() as tmp:
        files = generate(Path(tmp))
    if not a.check:
        a.dir.mkdir(parents=True, exist_ok=True)
        wrote = 0
        for name, text in files.items():
            path = a.dir / name
            # a fixture whose body and generator are unchanged keeps the
            # commit that generated it (no header churn)
            if path.exists() and sans_commit(path.read_text()) == \
                    sans_commit(text):
                continue
            path.write_text(text)
            wrote += 1
        print(f"wrote {wrote} of {len(files)} fixtures in {a.dir} "
              "(the rest unchanged)")
        return 0
    drift = 0
    for name, text in files.items():
        path = a.dir / name
        have = path.read_text() if path.exists() else ""
        diff = list(difflib.unified_diff(sans_commit(have),
                                         sans_commit(text),
                                         str(path), f"regenerated {name}"))
        if diff:
            drift += 1
            sys.stdout.writelines(diff)
    print(f"smoke fixtures: {len(files) - drift}/{len(files)} clean "
          f"in {a.dir}")
    return 1 if drift else 0


if __name__ == "__main__":
    sys.exit(main())
